import yaml, re
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_13/projects/contamcal-irt-calibration/registry.yaml') as f:
    data = yaml.safe_load(f)
exps = data.get('experiments', {})

# Also count Qwen 0.5B, 1.5B, 3B checkpoints
checkpoints = set()
for eid, e in exps.items():
    if e.get('conclusion') != 'success':
        continue
    if not ('sft' in eid.lower()):
        continue
    d = re.search(r'd(000|005|025|050|100)', eid.lower())
    s = re.search(r's(0|42|123)', eid.lower())

    # Detect model size
    if '05b' in eid.lower() or '0.5b' in eid.lower():
        model = 'qwen_05b'
    elif '15b' in eid.lower() or '1.5b' in eid.lower():
        model = 'qwen_15b'
    elif '3b' in eid.lower():
        model = 'qwen_3b'
    elif '7b' in eid.lower() and 'falcon' not in eid.lower() and 'olmo' not in eid.lower():
        model = 'qwen_7b'
    elif '14b' in eid.lower():
        model = 'qwen_14b'
    elif 'falcon' in eid.lower():
        model = 'falcon_7b'
    elif 'gemma' in eid.lower():
        model = 'gemma_9b'
    elif 'olmo' in eid.lower():
        model = 'olmo_7b'
    elif 'phi' in eid.lower():
        model = 'phi4_14b'
    elif 'llama' in eid.lower():
        model = 'llama_8b'
    else:
        model = 'unknown'

    if d:
        dosage = d.group(0)
        seed = s.group(1) if s else 'default'
        checkpoint = f'{model}_{dosage}_s{seed}'
        checkpoints.add(checkpoint)

print(f'Total distinct checkpoints: {len(checkpoints)}')
from collections import defaultdict
by_model = defaultdict(int)
for c in sorted(checkpoints):
    model = '_'.join(c.split('_')[:2])
    by_model[model] += 1
for m, cnt in sorted(by_model.items()):
    print(f'  {m}: {cnt}')
